  ('6540d728-0f5b-4a97-81f7-c2f20fbfc2eb', '44d46d84-d818-434e-9ddc-a9563bb78b52', '97bb026b-d13c-4a54-8b37-36ea90f27489', 'subtopic'::public.curated_course_node_type, 'Cement, aggregates, water, and admixtures', 'Students learn what each ingredient contributes and why small changes in materials can strongly affect strength, workability, and durability.', 0),
